import{_ as t,o,c as r,a3 as a}from"./chunks/framework.DQHjryjb.js";const u=JSON.parse('{"title":"Limitations","description":"","frontmatter":{"order":10},"headers":[],"relativePath":"reference/limitations.md","filePath":"reference/limitations.md"}'),i={name:"reference/limitations.md"};function n(d,e,s,c,h,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h1><h2 id="not-supported" tabindex="-1">Not supported <a class="header-anchor" href="#not-supported" aria-label="Permalink to &quot;Not supported&quot;">​</a></h2><p>Each of these fails loudly, so you find out during development rather than from wrong data.</p><table tabindex="0"><thead><tr><th></th><th>what happens</th><th>instead</th></tr></thead><tbody><tr><td>Application time and bitemporal history</td><td>not implemented; the API leaves room to add it without breaking changes</td><td>PostgreSQL 19&#39;s <code>FOR PORTION OF</code> for application time</td></tr><tr><td><code>Include</code> on a historical query</td><td><code>NotSupportedException</code></td><td>a second historical query keyed on the foreign key</td></tr><tr><td><code>AsOf</code> / <code>AllVersions</code> after another operator</td><td>throws</td><td>put them first, on the <code>DbSet</code></td></tr><tr><td><code>ExecuteUpdate</code> / <code>ExecuteDelete</code> on a historical query</td><td><code>NotSupportedException</code></td><td>run them on a normal query of the current rows</td></tr><tr><td>Owned references and complex properties on a temporal entity</td><td><code>NotSupportedException</code> at model build</td><td>a standalone entity without them</td></tr><tr><td>Inheritance hierarchies</td><td>rejected at model build</td><td>map the temporal entity on its own</td></tr><tr><td>Restoring an entity to an old version</td><td>saving a historical snapshot throws <code>InvalidOperationException</code></td><td><a href="/hindsight-efcore/1.3/querying/restrictions#history-is-read-only">copy the values</a> onto the current entity</td></tr><tr><td>Removing a primary-key property of a temporal entity</td><td><code>InvalidOperationException</code> at model build</td><td>keep it, or remove <code>IsTemporal()</code></td></tr><tr><td>Changing a property&#39;s store type, precision/scale, max length or converter under the same column name</td><td><code>InvalidOperationException</code> at model build</td><td><a href="/hindsight-efcore/1.3/migrations/schema-evolution#changing-a-property-s-type">give it a different column name</a> instead</td></tr><tr><td>Database providers other than Npgsql</td><td><code>InvalidOperationException</code> on first use</td><td>none planned</td></tr><tr><td>Retention and partitioning of history</td><td>history grows without bound</td><td>planned for a later major version; the schema allows it without migrating existing data</td></tr></tbody></table><h2 id="known-trade-offs" tabindex="-1">Known trade-offs <a class="header-anchor" href="#known-trade-offs" aria-label="Permalink to &quot;Known trade-offs&quot;">​</a></h2><h3 id="interceptor-writer" tabindex="-1">Interceptor writer <a class="header-anchor" href="#interceptor-writer" aria-label="Permalink to &quot;Interceptor writer&quot;">​</a></h3><ul><li><strong>It only sees <code>SaveChanges</code>.</strong> <code>ExecuteUpdate</code>, <code>ExecuteDelete</code>, raw SQL and other processes write no history. The trigger writer records them. See <a href="/hindsight-efcore/1.3/writing/interceptor">Interceptor writer</a>. An analyzer (<code>HDST001</code>) catches the common case at compile time — a bulk operation against an entity your project configures with <code>IsTemporal()</code> — but it cannot see which writer you actually use, so it fires at <code>Info</code> severity regardless: see <a href="/hindsight-efcore/1.3/writing/interceptor#hdst001-bulk-operations-on-a-temporal-entity">the analyzer diagnostic</a>.</li><li><strong>Your own <code>SaveChangesInterceptor</code> runs after Hindsight&#39;s.</strong> A change it makes inside <code>SavingChanges</code> reaches the table without a version. <a href="/hindsight-efcore/1.3/writing/interceptor#your-own-interceptors-run-after-hindsights">Details</a>.</li><li><strong>Deleting costs one extra round trip</strong>: the row is re-read by key (<code>SELECT … FOR UPDATE</code>) so the tombstone holds real values. If the row is already gone, the save throws.</li><li><strong>A failed history write leaves deleted entities detached.</strong> The transaction rolls back correctly, and <code>Added</code> / <code>Modified</code> entities are restored for a retry, but a <code>Deleted</code> one must be queried and removed again. <a href="/hindsight-efcore/1.3/writing/interceptor#if-the-history-write-fails">Details</a>.</li><li><strong>A retried save of a restored <code>Added</code> entity with a store-generated key sends the key it received in the rolled-back transaction.</strong> With <code>GENERATED BY DEFAULT AS IDENTITY</code> (Npgsql&#39;s default) the retry succeeds and reuses that id. With <code>GENERATED ALWAYS AS IDENTITY</code> (<code>UseIdentityAlwaysColumn()</code>) PostgreSQL rejects it with error <code>428C9</code> until you reset the key property to <code>0</code>.</li></ul><h3 id="both-writers" tabindex="-1">Both writers <a class="header-anchor" href="#both-writers" aria-label="Permalink to &quot;Both writers&quot;">​</a></h3><ul><li><strong>Bulk writes have no change context.</strong> Under the trigger writer, <code>ExecuteUpdate</code>, <code>ExecuteDelete</code> and raw SQL are recorded with <code>NULL</code> change-context columns.</li><li><strong>The writers differ in two observable ways</strong>: the source of timestamps (<code>TimeProvider</code> or <code>now()</code>), and whether an update that sets a column to its current value writes a version. See <a href="/hindsight-efcore/1.3/writing/history-writers#differences-you-can-observe">Choosing a history writer</a>.</li><li><strong>The change context is asserted by the application</strong>, not guaranteed by the database. See the <a href="/hindsight-efcore/1.3/writing/change-context#trust-model">trust model</a>.</li><li><strong><code>EnableRetryOnFailure()</code> needs your own transaction</strong> around a save that Hindsight would otherwise wrap in one. See <a href="/hindsight-efcore/1.3/writing/transactions#enableretryonfailure">Transactions</a>.</li><li><strong>Pooled and factory-created contexts need a singleton change-context provider.</strong> See <a href="/hindsight-efcore/1.3/writing/change-context#pooled-and-factory-created-contexts">Change context</a>.</li></ul>',9)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
